export default `@charset "UTF-8";:root{--color-brand-blush: #f8dce5;--color-brand-rose: #eba3c2;--color-brand-pink: #e84d8e;--color-brand-crimson: #d33041;--color-brand-rosewood: #8e5a5a;--color-brand-logo-bg: #e5b8b8;--color-ui-background: var(--color-brand-blush);--color-ui-surface: #ffffff;--color-ui-text: #2a1f22;--color-ui-text-muted: var(--color-brand-rosewood);--color-ui-primary: var(--color-brand-crimson);--color-ui-primary-hover: #b62736;--color-ui-accent: var(--color-brand-pink);--color-ui-border: #e8c8d0;--color-ui-focus-ring: var(--color-brand-pink);--font-display: "Cinzel", "Cormorant Garamond", "Playfair Display", Georgia, serif;--font-body: "Lato", "Source Sans 3", "Mulish", "Helvetica Neue", Arial, sans-serif;--font-script: "Allura", "Great Vibes", "Pinyon Script", cursive;--space-1: .25rem;--space-2: .5rem;--space-3: .75rem;--space-4: 1rem;--space-5: 1.5rem;--space-6: 2rem;--space-8: 3rem;--space-12: 4.5rem;--content-max-width: 1100px;--content-padding-inline: 1.25rem;--radius-sm: 4px;--radius-md: 8px;--radius-lg: 12px;--radius-pill: 999px}*,*:before,*:after{box-sizing:border-box}html,body{margin:0;padding:0;min-height:100%}html{font-size:16px;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}body{font-family:var(--font-body);color:var(--color-ui-text);background:linear-gradient(to bottom,var(--color-brand-blush) 0%,var(--color-brand-rose) 100%);background-repeat:no-repeat;min-height:100vh;line-height:1.5}img{max-width:100%;height:auto}h1,h2,h3{font-family:var(--font-display);font-weight:600;letter-spacing:.02em;line-height:1.2;color:var(--color-brand-rosewood)}a{color:var(--color-brand-crimson)}button{font-family:inherit}:focus-visible{outline:2px solid var(--color-ui-focus-ring);outline-offset:2px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
`;